<template>
  <div class="page" :class="{'-hideVideo': isExitModalVisible}">
    <div class="panel">
      <h1>JW Player 8.0.12 + Vue 2</h1>
      <p class="desc">
        页面通过 <code>script</code> 标签加载 JW Player，默认播放
        <code>{{ defaultSource }}</code>。
      </p>

      <label class="label" for="hlsUrl">HLS 地址</label>
      <div class="toolbar">
        <input id="hlsUrl" v-model.trim="source" class="input" type="text" />
        <button class="button" type="button" @click="reloadPlayer">重新加载</button>
        <button class="button button-close" type="button" @click="openExitModal">
          关闭播放
        </button>
      </div>

      <div v-if="!isPlayerClosed" id="jwplayer-demo"></div>
      <div v-else class="player-closed">
        已退出播放，点击“重新加载”可重新创建播放器。
      </div>

      <div class="meta">
        <div><strong>发布编号：</strong><code>{{ buildId }}</code></div>
        <div><strong>本地示例文件：</strong><code>public/sample.m3u8</code></div>
        <div><strong>阻止快进：</strong><code>{{ preventSeeking ? "开启" : "关闭" }}</code></div>
        <div>
          <strong>当前播放地址：</strong><code>{{ source }}</code>
        </div>
      </div>
    </div>

    <dialog
      ref="exitDialog"
      class="modal"
      aria-labelledby="exit-modal-title"
      @cancel.prevent="continueWatching"
    >
      <h2 id="exit-modal-title">是否要退出播放？</h2>
      <p>弹出确认框时会先暂停播放器，继续观看后会恢复播放。</p>
      <div class="modal-actions">
        <button class="button button-secondary" type="button" @click="continueWatching">
          继续观看
        </button>
        <button class="button button-close" type="button" @click="exitWatching">
          退出观看
        </button>
      </div>
    </dialog>
  </div>
</template>

<script>
const defaultSource = `${process.env.BASE_URL}sample.m3u8`;
const buildId = process.env.VUE_APP_BUILD_ID || "dev-build";

export default {
  name: "App",
  data() {
    return {
      buildId,
      defaultSource,
      source: defaultSource,
      isExitModalVisible: false,
      isPlayerClosed: false,
      shouldResumeAfterModal: false,
      preventSeeking: true,
      preventRewind: false,
      maxProgressTime: 0,
      seekToleranceSeconds: 1.1,
      nativeSeekGuard: null,
      nativeVideoObserver: null,
      blockedSeekPosition: null,
      seekRestoreFrame: null,
      isRestoringSeek: false,
    };
  },
  mounted() {
    this.setupPlayer();
  },
  beforeDestroy() {
    this.clearNativeSeekGuard();
    if (window.jwplayer) {
      window.jwplayer("jwplayer-demo").remove();
    }

    this.closeExitDialog();
  },
  methods: {
    getPlayer() {
      return window.jwplayer ? window.jwplayer("jwplayer-demo") : null;
    },
    getExitDialog() {
      return this.$refs.exitDialog;
    },
    showExitDialog() {
      const dialog = this.getExitDialog();
      if (dialog && !dialog.open) {
        dialog.showModal();
      }
    },
    resetSeekGuard() {
      this.maxProgressTime = 0;
      this.blockedSeekPosition = null;
      this.isRestoringSeek = false;
      if (this.seekRestoreFrame !== null) {
        window.cancelAnimationFrame(this.seekRestoreFrame);
        this.seekRestoreFrame = null;
      }
    },
    recordAllowedPosition(position) {
      if (!this.isRestoringSeek && this.blockedSeekPosition === null) {
        this.maxProgressTime = Math.max(this.maxProgressTime, position);
      }
    },
    blockForwardSeek(position) {
      const isForwardSeek =
        this.preventSeeking &&
        !this.isRestoringSeek &&
        position - this.maxProgressTime > this.seekToleranceSeconds;

      if (isForwardSeek) {
        this.blockedSeekPosition = this.maxProgressTime;
      }

      return isForwardSeek;
    },
    scheduleBlockedSeekRestore(player) {
      if (this.blockedSeekPosition === null || this.seekRestoreFrame !== null) {
        return;
      }

      this.seekRestoreFrame = window.requestAnimationFrame(() => {
        const allowedPosition = this.blockedSeekPosition;
        const nativeVideo = this.nativeSeekGuard && this.nativeSeekGuard.video;

        this.seekRestoreFrame = null;
        this.blockedSeekPosition = null;
        this.isRestoringSeek = true;

        player.seek(allowedPosition);
        if (nativeVideo) {
          nativeVideo.currentTime = allowedPosition;
        }

        window.setTimeout(() => {
          this.isRestoringSeek = false;
        }, 0);
      });
    },
    clearNativeSeekGuard() {
      if (this.seekRestoreFrame !== null) {
        window.cancelAnimationFrame(this.seekRestoreFrame);
        this.seekRestoreFrame = null;
      }

      if (this.nativeVideoObserver) {
        this.nativeVideoObserver.disconnect();
        this.nativeVideoObserver = null;
      }

      if (this.nativeSeekGuard) {
        const { video, onSeeking, onSeeked, onTimeUpdate } = this.nativeSeekGuard;
        video.removeEventListener("seeking", onSeeking);
        video.removeEventListener("seeked", onSeeked);
        video.removeEventListener("timeupdate", onTimeUpdate);
        this.nativeSeekGuard = null;
      }
    },
    bindNativeSeekGuard() {
      this.clearNativeSeekGuard();

      const container = document.querySelector("#jwplayer-demo");
      if (!container) {
        return;
      }

      const attachToVideo = () => {
        const video = container.querySelector("video");
        if (!video || (this.nativeSeekGuard && this.nativeSeekGuard.video === video)) {
          return;
        }

        if (this.nativeSeekGuard) {
          const { video: previousVideo, onSeeking, onSeeked, onTimeUpdate } =
            this.nativeSeekGuard;
          previousVideo.removeEventListener("seeking", onSeeking);
          previousVideo.removeEventListener("seeked", onSeeked);
          previousVideo.removeEventListener("timeupdate", onTimeUpdate);
        }

        const onSeeking = () => {
          this.blockForwardSeek(video.currentTime);
        };
        const onSeeked = () => {
          const player = this.getPlayer();
          if (!player) {
            return;
          }

          if (this.blockedSeekPosition !== null) {
            this.scheduleBlockedSeekRestore(player);
            return;
          }

          this.recordAllowedPosition(video.currentTime);
        };
        const onTimeUpdate = () => {
          const player = this.getPlayer();
          if (!player) {
            return;
          }

          if (this.blockForwardSeek(video.currentTime)) {
            this.scheduleBlockedSeekRestore(player);
            return;
          }

          this.recordAllowedPosition(video.currentTime);
        };

        video.addEventListener("seeking", onSeeking);
        video.addEventListener("seeked", onSeeked);
        video.addEventListener("timeupdate", onTimeUpdate);
        this.nativeSeekGuard = { video, onSeeking, onSeeked, onTimeUpdate };
      };

      attachToVideo();
      this.nativeVideoObserver = new MutationObserver(attachToVideo);
      this.nativeVideoObserver.observe(container, {
        childList: true,
        subtree: true,
      });
    },
    bindSeekGuard(player) {
      player.on("seek", (event) => {
        if (typeof event.offset !== "number") {
          return;
        }

        this.blockForwardSeek(event.offset);
      });

      player.on("time", (event) => {
        if (this.blockForwardSeek(event.position)) {
          this.scheduleBlockedSeekRestore(player);
          return;
        }

        this.recordAllowedPosition(event.position);
      });

      player.on("seeked", () => {
        this.scheduleBlockedSeekRestore(player);
      });

      player.on("complete", () => {
        this.recordAllowedPosition(player.getDuration());
      });

      player.on("ready", () => {
        this.$nextTick(() => {
          this.bindNativeSeekGuard();
        });
      });
    },
    closeExitDialog() {
      const dialog = this.getExitDialog();
      if (dialog && dialog.open) {
        dialog.close();
      }
    },
    setupPlayer() {
      if (!window.jwplayer) {
        throw new Error("JW Player script failed to load.");
      }

      this.resetSeekGuard();
      const player = this.getPlayer();

      player.setup({
        file: this.source,
        width: "100%",
        aspectratio: "16:9",
        image: "https://dummyimage.com/1280x720/0f172a/ffffff&text=JW+Player+HLS+Demo",
        title: "Sample HLS Stream",
        autostart: false,
        mute: false,
      });

      this.bindSeekGuard(player);
    },
    reloadPlayer() {
      const player = this.getPlayer();
      if (player && !this.isPlayerClosed) {
        this.clearNativeSeekGuard();
        player.remove();
      }

      this.closeExitDialog();
      this.isExitModalVisible = false;
      this.isPlayerClosed = false;
      this.$nextTick(() => {
        this.setupPlayer();
      });
    },
    openExitModal() {
      const player = this.getPlayer();
      if (player) {
        this.shouldResumeAfterModal = player.getState() === "playing";
        player.pause(true);
      }

      this.isExitModalVisible = true;
      this.$nextTick(() => {
        this.showExitDialog();
      });
    },
    continueWatching() {
      this.closeExitDialog();
      this.isExitModalVisible = false;
      const player = this.getPlayer();
      if (player && this.shouldResumeAfterModal) {
        player.play(true);
      }
      this.shouldResumeAfterModal = false;
    },
    exitWatching() {
      const player = this.getPlayer();
      if (player) {
        this.clearNativeSeekGuard();
        player.remove();
      }

      this.closeExitDialog();
      this.isExitModalVisible = false;
      this.isPlayerClosed = true;
      this.shouldResumeAfterModal = false;
    },
  },
};
</script>

<style>
.page {
  min-height: 100vh;
  padding: 40px 20px;
  background: #f8fafc;
  color: #0f172a;
  font-family: Arial, Helvetica, sans-serif;
}

.-hideVideo video {
  display: none;
}

.panel {
  max-width: 960px;
  margin: 0 auto;
  background: #ffffff;
  border-radius: 16px;
  padding: 24px;
  box-shadow: 0 18px 45px rgba(15, 23, 42, 0.08);
}

h1 {
  margin: 0 0 12px;
  font-size: 28px;
}

.desc {
  margin: 0 0 20px;
  line-height: 1.6;
}

.label {
  display: block;
  margin-bottom: 8px;
  font-weight: 700;
}

.toolbar {
  display: flex;
  gap: 12px;
  margin-bottom: 20px;
  flex-wrap: wrap;
}

.input {
  flex: 1;
  min-width: 0;
  padding: 12px 14px;
  border: 1px solid #cbd5e1;
  border-radius: 10px;
  font-size: 14px;
}

.button {
  border: 0;
  border-radius: 10px;
  padding: 12px 18px;
  background: #2563eb;
  color: #ffffff;
  font-size: 14px;
  cursor: pointer;
}

.button-close {
  background: #dc2626;
}

.button-secondary {
  background: #475569;
}

.player-closed {
  display: grid;
  place-items: center;
  min-height: 280px;
  margin-top: 8px;
  border: 1px dashed #94a3b8;
  border-radius: 12px;
  background: #f8fafc;
  color: #475569;
  text-align: center;
  padding: 24px;
}

.meta {
  margin-top: 20px;
  display: grid;
  gap: 8px;
  line-height: 1.6;
}

.modal {
  width: min(100%, 420px);
  background: #ffffff;
  border: 0;
  border-radius: 16px;
  padding: 24px;
  box-shadow: 0 24px 60px rgba(15, 23, 42, 0.2);
}

.modal::backdrop {
  background: rgba(15, 23, 42, 0.55);
}

.modal h2 {
  margin: 0 0 12px;
  font-size: 22px;
}

.modal p {
  margin: 0 0 20px;
  color: #475569;
  line-height: 1.6;
}

.modal-actions {
  display: flex;
  justify-content: flex-end;
  gap: 12px;
}

code {
  background: #e2e8f0;
  border-radius: 6px;
  padding: 2px 6px;
}

/* // For HLS streams the "time" event based seek-back can be unreliable,
// so also disable the progress bar drag/click directly in the DOM. */
.panel.-no-seek {
    .jw-slider-time,
    .jw-slider-time .jw-slider-container,
    .jw-slider-time .jw-knob {
        @apply pointer-events-none cursor-default;
    }
    .jw-slider-time .jw-knob {
        transform: translate(-50%, -50%) scale(1);
    }
}
</style>
